pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newOwner, address caller) public {
        vm.assume(caller != address(0));
        vm.assume(newOwner != address(0));
        // caller must be the current owner to satisfy the onlyOwner modifier
        vm.prank(c.owner());
        vm.startPrank(c.owner());
        c.setOwner(caller);
        vm.stopPrank();

        address ownerBefore = c.owner();

        vm.prank(caller);
        uint256 gasBefore = gasleft();
        try c.setOwner(newOwner) returns (bool) {
            // success path: owner must change to newOwner
            assertTrue(c.owner() == newOwner);
        } catch {
            // revert path: owner must stay unchanged
            assertTrue(c.owner() == ownerBefore);
        }
    }
}

