pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newOwner) public {
        // Owner is the deployer (this contract). We prank as the owner.
        vm.prank(address(this));
        try c.setOwner(newOwner) returns (bool success) {
            // On the reference, this call must succeed and update owner.
            // Assert the postcondition: owner equals the newOwner.
            assertTrue(c.owner() == newOwner);
        } catch {
            // On the buggy version, the call reverts.
            // Assert false to signal that revert for the owner is a violation.
            assertTrue(false);
        }
    }
}

