pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address ownerCandidate, address newOwner) public {
        vm.assume(ownerCandidate != address(0));
        vm.assume(newOwner != address(0));
        // Use a fresh candidate as owner via prank deployment is not possible; 
        // we use the default owner (this contract) for prank.
        // We check the condition: if msg.sender == owner, the return must be true.
        // We prank as the test contract which is the current owner.
        vm.prank(address(this));
        bool success = c.setOwner(newOwner);
        assertTrue(success);
    }
}

